import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64

.visible .entry bn2d_onepass(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 running_mean_ptr,
    .param .u64 running_var_ptr,
    .param .u64 nb_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .f32 eps,
    .param .f32 momentum,
    .param .u32 training,
    .param .u32 track_stats
)
{
    .reg .pred  %p<12>;
    .reg .b32   %r<40>;
    .reg .b64   %rd<60>;
    .reg .f32   %f<60>;

    // Shared memory for per-block reduction and scalars
    .shared .align 4 .f32 sh_sum[256];
    .shared .align 4 .f32 sh_sumsq[256];
    .shared .align 4 .f32 sh_used_mean;
    .shared .align 4 .f32 sh_used_invstd;
    .shared .align 4 .f32 sh_gamma;
    .shared .align 4 .f32 sh_beta;

    // Load params
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [y_ptr];
    ld.param.u64 %rd3, [weight_ptr];
    ld.param.u64 %rd4, [bias_ptr];
    ld.param.u64 %rd5, [running_mean_ptr];
    ld.param.u64 %rd6, [running_var_ptr];
    ld.param.u64 %rd7, [nb_ptr];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [C];
    ld.param.u32 %r3,  [H];
    ld.param.u32 %r4,  [W];
    ld.param.f32 %f1,  [eps];
    ld.param.f32 %f2,  [momentum];
    ld.param.u32 %r5,  [training];
    ld.param.u32 %r6,  [track_stats];

    // Thread/block indices
    mov.u32 %r10, %tid.x;      // tid
    mov.u32 %r11, %ctaid.x;    // block/channel index c
    mov.u32 %r12, %ntid.x;     // blockDim.x

    // Bounds check on channel index
    setp.ge.u32 %p0, %r11, %r2;
    @%p0 bra DONE;

    // Compute sizes
    mul.lo.u32 %r13, %r3, %r4;      // HW
    mul.lo.u32 %r14, %r2, %r13;     // CHW
    mul.lo.u32 %r15, %r1, %r13;     // M = N*HW

    // Precompute base index within channel: base_c = c*HW
    mul.lo.u32 %r16, %r11, %r13;    // base_c

    // Initialize accumulators
    mov.f32 %f10, 0f00000000; // sum
    mov.f32 %f11, 0f00000000; // sumsq

    // Loop over all M elements with stride blockDim.x
    mov.u32 %r17, %r10;  // idx = tid
LOOP_ACCUM:
    setp.ge.u32 %p1, %r17, %r15;
    @%p1 bra LOOP_ACCUM_END;

    // n = idx / HW; t2 = idx % HW
    div.u32 %r18, %r17, %r13;    // n
    rem.u32 %r19, %r17, %r13;    // t2

    // offset_elem = n*CHW + base_c + t2
    mul.wide.u32 %rd20, %r18, %r14;      // (u64) n*CHW
    cvt.u64.u32 %rd21, %r16;             // base_c
    add.s64 %rd20, %rd20, %rd21;         // n*CHW + base_c
    cvt.u64.u32 %rd22, %r19;             // t2
    add.s64 %rd20, %rd20, %rd22;         // element index
    shl.b64 %rd23, %rd20, 2;             // *4 bytes

    // addr = x_ptr + off
    add.s64 %rd24, %rd1, %rd23;
    ld.global.f32 %f12, [%rd24];

    // sum += val; sumsq += val*val
    fma.rn.f32 %f11, %f12, %f12, %f11;
    add.f32 %f10, %f10, %f12;

    // idx += blockDim.x
    add.u32 %r17, %r17, %r12;
    bra LOOP_ACCUM;
LOOP_ACCUM_END:

    // Write partial sums to shared memory
    // sh_sum[tid] = sum; sh_sumsq[tid] = sumsq
    {
        .reg .u64 %rs_base, %rq_off, %rs_addr;
        cvta.to.shared.u64 %rs_base, sh_sum;
        mul.wide.u32 %rq_off, %r10, 4;
        add.s64 %rs_addr, %rs_base, %rq_off;
        st.shared.f32 [%rs_addr], %f10;

        cvta.to.shared.u64 %rs_base, sh_sumsq;
        add.s64 %rs_addr, %rs_base, %rq_off;
        st.shared.f32 [%rs_addr], %f11;
    }
    bar.sync 0;

    // Block reduction
    // stride = blockDim.x >> 1
    shr.u32 %r20, %r12, 1;

REDUCE_LOOP:
    setp.eq.u32 %p2, %r20, 0;
    @%p2 bra REDUCE_DONE;

    setp.lt.u32 %p3, %r10, %r20;
    @!%p3 bra SKIP_REDUCE;

    // sh_sum[tid] += sh_sum[tid+stride]
    {
        .reg .u64 %base, %addr0, %addr1, %off0, %off1;
        cvta.to.shared.u64 %base, sh_sum;
        mul.wide.u32 %off0, %r10, 4;
        add.s64 %addr0, %base, %off0;

        add.u32 %r21, %r10, %r20;
        mul.wide.u32 %off1, %r21, 4;
        add.s64 %addr1, %base, %off1;

        ld.shared.f32 %f20, [%addr0];
        ld.shared.f32 %f21, [%addr1];
        add.f32 %f20, %f20, %f21;
        st.shared.f32 [%addr0], %f20;
    }

    // sh_sumsq[tid] += sh_sumsq[tid+stride]
    {
        .reg .u64 %base, %addr0, %addr1, %off0, %off1;
        cvta.to.shared.u64 %base, sh_sumsq;
        mul.wide.u32 %off0, %r10, 4;
        add.s64 %addr0, %base, %off0;

        add.u32 %r22, %r10, %r20;
        mul.wide.u32 %off1, %r22, 4;
        add.s64 %addr1, %base, %off1;

        ld.shared.f32 %f22, [%addr0];
        ld.shared.f32 %f23, [%addr1];
        add.f32 %f22, %f22, %f23;
        st.shared.f32 [%addr0], %f22;
    }

SKIP_REDUCE:
    bar.sync 0;
    shr.u32 %r20, %r20, 1;
    bra REDUCE_LOOP;

REDUCE_DONE:

    // Thread 0 computes mean/var, selects stats, updates running stats, sets broadcast scalars
    setp.eq.u32 %p4, %r10, 0;
    @!%p4 bra POST_SETUP;

    // Load total sum and sumsq from shmem index 0
    {
        .reg .u64 %b, %a0;
        cvta.to.shared.u64 %b, sh_sum;
        mov.u64 %a0, %b;
        ld.shared.f32 %f30, [%a0]; // total sum

        cvta.to.shared.u64 %b, sh_sumsq;
        mov.u64 %a0, %b;
        ld.shared.f32 %f31, [%a0]; // total sumsq
    }

    // mean = sum / M; var = sumsq / M - mean*mean
    cvt.rn.f32.u32 %f32, %r15;          // float(M)
    div.rn.f32 %f33, %f30, %f32;        // mean
    div.rn.f32 %f34, %f31, %f32;        // E[x^2]
    mul.f32 %f35, %f33, %f33;           // mean^2
    add.f32 %f36, %f34, -%f35;          // var

    // Load running stats, gamma, beta for channel c
    // Compute address offset for channel index c
    {
        .reg .u64 %off_c4;
        mul.wide.u32 %off_c4, %r11, 4;

        // weight[c]
        add.s64 %rd30, %rd3, %off_c4;
        ld.global.f32 %f40, [%rd30];

        // bias[c]
        add.s64 %rd31, %rd4, %off_c4;
        ld.global.f32 %f41, [%rd31];

        // running mean/var
        add.s64 %rd32, %rd5, %off_c4;
        add.s64 %rd33, %rd6, %off_c4;
        ld.global.f32 %f42, [%rd32]; // running_mean[c]
        ld.global.f32 %f43, [%rd33]; // running_var[c]
    }

    // Determine which stats to use
    // pTraining = training != 0
    setp.ne.u32 %p5, %r5, 0;
    // pTrack = track_stats != 0
    setp.ne.u32 %p6, %r6, 0;
    // pNotTraining = !p5
    not.pred %p7, %p5;
