    setp.ge.u32 %p12, %r30, %r15;
    @%p12 bra LOOP_OUT_END;
    // n = idx / HW; t2 = idx % HW
    div.u32 %r31, %r30, %r13;    // n
    rem.u32 %r32, %r30, %r13;    // t2
