_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("bn2d_onepass")

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer("running_mean", torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer("running_var", torch.ones(num_features, dtype=torch.float32))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))
        self.eps = 1e-5
        self.momentum = 0.1
        self.track_running_stats = True

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device for PTX execution."
        assert x.dtype == torch.float32, "Only float32 tensors are supported."
        N, C, H, W = x.shape
        assert C == self.num_features, "Channel dimension must match num_features."

        y = torch.empty((N, C, H, W), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        module.launch(
            "bn2d_onepass",
            grid=(C, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x,
                y,
                self.weight,
                self.bias,
                self.running_mean,
                self.running_var,
                self.num_batches_tracked,
                i32(N),
                i32(C),
                i32(H),
                i32(W),
                f32(float(self.eps)),
                f32(float(self.momentum)),
                u32(1 if self.training else 0),
                u32(1 if self.track_running_stats else 0),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
